llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In humans, phytoene showed absolute oral bioavailability of 58.5 ± 18.9%, far above the 20% threshold; this is the most direct high-bioavailability anchor for a related carotenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A compartmental-model estimate in humans put phytoene bioavailability at 58%, independently corroborating high absorption for this carotenoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "In healthy humans, 13C-labeled all-trans lycopene had an estimated bioavailability of 23.2 ± 8%, above the 20% threshold, showing that related carotenoids can exceed the cutoff.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lycopene systemic availability from capsules was only ~2.6%, below the threshold; however, this reflects systemic appearance rather than true absolute absorption and is formulation-dependent.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C06"],
      "claim": "Mulberroside A was reported to have low oral bioavailability due to rapid intestinal deglycosylation, but this is a different chemical class and not transferable to a carotenoid-like query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The most direct and endpoint-matched evidence (human absolute bioavailability of phytoene) is high, and related 13C-lycopene estimates also exceed 20%; the low lycopene systemic-availability values are less direct and formulation-dependent, so the balance supports high bioavailability.",
  "evidence_gaps": [
    "No direct experimental measurement for the query molecule; the query structure is omitted, so the degree of similarity to phytoene/lycopene is not directly assessable.",
    "Lycopene bioavailability is highly dependent on food matrix, formulation, and measurement method (systemic appearance vs compartmental absorption), causing conflicting records.",
    "Mulberroside A is chemically unrelated and provides little transferable information."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

